// Integer base-2 softmax for one attention row — no exp, no divider, no float.
// Mirrors python/approx.py::softmax_pow2 (tables from pwl_tables.h, generated by deploy.py).
//
//  in : s[L]  log2-domain scores, Q7.8 int16 (log2(e)/sqrt(dh) already folded into W_q)
//  out: p[L]  probabilities, Q1.15 (sum ~ 32768)
//
//  u = s - max <= 0 ; u = i + f  (i = u>>8, f = u&255)
//  2^f   : 8-segment PWL on top 3 bits of f, 5-bit interpolation  -> Q2.14
//  2^u   : (2^f) >> (-i)                                           -> barrel shifter
//  1/sum : leading-one detector + 16-segment PWL on mantissa       -> Q1.15
#pragma once
#include <stdint.h>

#ifndef N_EXP   // defaults identical to approx.py (normally included from pwl_tables.h)
#define N_EXP 8
#define N_RECIP 16
static const int32_t EXP_KNOTS_Q14[9] = {16384, 17867, 19484, 21247, 23170, 25268, 27554, 30048, 32768};
static const int32_t RECIP_KNOTS_Q15[17] = {32768, 30840, 29127, 27594, 26214, 24966, 23831, 22795, 21845,
                                            20972, 20165, 19418, 18725, 18079, 17476, 16913, 16384};
#endif

template <int L>
void softmax_pow2_row(const int16_t s[L], uint16_t p[L]) {
#pragma HLS INLINE
    int16_t mx = s[0];
MAX:
    for (int j = 1; j < L; j++) mx = (s[j] > mx) ? s[j] : mx;

    int32_t e2[L];
    int32_t sum = 0;
EXP:
    for (int j = 0; j < L; j++) {
#pragma HLS PIPELINE II = 1
        int32_t u = (int32_t)s[j] - mx;          // <= 0, Q.8
        int32_t i = u >> 8;                      // floor (arithmetic shift)
        int32_t f = u & 0xFF;                    // frac in [0,256)
        int32_t idx = f >> 5, t = f & 31;        // 8 segments x 32 steps
        int32_t y0 = EXP_KNOTS_Q14[idx], y1 = EXP_KNOTS_Q14[idx + 1];
        int32_t v = y0 + (((y1 - y0) * t) >> 5); // 2^f in Q2.14
        int32_t sh = -i;
        e2[j] = (sh >= 16) ? 0 : (v >> sh);
        sum += e2[j];
    }
    // leading-one detector: sum = m * 2^e, 1.0 == 2^14
    int msb = 0;
LOD:
    for (int b = 0; b < 31; b++) if ((sum >> b) & 1) msb = b;
    int e = msb - 14;                            // >= 0 because sum >= 1.0
    int32_t norm = (msb >= 15) ? (sum >> (msb - 15)) : (sum << (15 - msb));   // Q1.15 in [1,2)
    int32_t frac = norm - 32768;                 // 15 bits
    int32_t idx = frac >> 11, t = frac & 0x7FF;  // 16 segments x 2048 steps
    int32_t r0 = RECIP_KNOTS_Q15[idx], r1 = RECIP_KNOTS_Q15[idx + 1];
    int32_t rm = r0 + (((r1 - r0) * t) >> 11);   // 1/m in Q1.15
NORM:
    for (int j = 0; j < L; j++) {
#pragma HLS PIPELINE II = 1
        int64_t q = ((int64_t)e2[j] * rm) >> (14 + e);   // Q2.14 * Q1.15 -> Q1.15
        p[j] = (uint16_t)(q > 32767 ? 32767 : q);
    }
}
